import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const SCRIPT_PATH = fileURLToPath(import.meta.url);
const REPOSITORY_ROOT = path.resolve(path.dirname(SCRIPT_PATH), "..");
export const RUST_PROTOCOL_SOURCE = path.join(
  REPOSITORY_ROOT,
  "rust",
  "crates",
  "ncx-protocol",
  "src",
  "lib.rs",
);
export const TYPESCRIPT_PROTOCOL_TARGET = path.join(
  REPOSITORY_ROOT,
  "rust",
  "gui",
  "src",
  "lib",
  "protocol-version.ts",
);

const GENERATED_HEADER =
  "// @generated by scripts/check-protocol-version.mjs; do not edit by hand.\n" +
  "// The Rust protocol module is the single source of truth for this contract.\n";

/** Extract the one public protocol version declaration from the Rust source. */
export function extractProtocolVersion(source, sourceName = "Rust protocol source") {
  const matches = [
    ...source.matchAll(/^\s*pub\s+const\s+PROTOCOL_VERSION\s*:\s*u32\s*=\s*(\d+)\s*;\s*$/gm),
  ];
  if (matches.length !== 1) {
    throw new Error(
      `${sourceName} must contain exactly one ` +
        "`pub const PROTOCOL_VERSION: u32 = <integer>;` declaration",
    );
  }
  const version = Number(matches[0][1]);
  if (!Number.isSafeInteger(version) || version < 1) {
    throw new Error(`${sourceName} contains an invalid protocol version: ${matches[0][1]}`);
  }
  return version;
}

function pascalCaseToCamelCase(name) {
  return `${name[0].toLowerCase()}${name.slice(1)}`;
}

/**
 * Extract top-level ClientRequest variants using the same names serde exposes
 * under `rename_all = "camelCase"`. Keeping this list generated prevents a
 * frontend typo or a newly added Rust request from silently drifting apart.
 */
export function extractProtocolMethods(source, sourceName = "Rust protocol source") {
  const marker = /pub\s+enum\s+ClientRequest\s*\{/m.exec(source);
  if (!marker) throw new Error(`${sourceName} does not contain ClientRequest`);

  const body = source.slice(marker.index + marker[0].length);
  const methods = [];
  let depth = 1;
  let pendingRename = null;
  for (const line of body.split(/\r?\n/)) {
    const code = line.replace(/\/\/.*$/, "");
    if (depth === 1) {
      const rename = /#\[serde\([^\]]*\brename\s*=\s*"([^"]+)"[^\]]*\)\]/.exec(code);
      if (rename) pendingRename = rename[1];
      const variant = /^[ \t]{4}([A-Z][A-Za-z0-9_]*)\s*(?:\{|,)/.exec(code);
      if (variant) {
        methods.push(pendingRename || pascalCaseToCamelCase(variant[1]));
        pendingRename = null;
      }
    }
    depth += (code.match(/\{/g) || []).length;
    depth -= (code.match(/\}/g) || []).length;
    if (depth === 0) break;
  }
  if (depth !== 0 || methods.length === 0) {
    throw new Error(`${sourceName} contains an invalid or empty ClientRequest enum`);
  }
  if (new Set(methods).size !== methods.length) {
    throw new Error(`${sourceName} contains duplicate ClientRequest method names`);
  }
  return methods;
}

/** Render the checked-in TypeScript module derived from the Rust contract. */
export function renderProtocolModule(version, methods = []) {
  if (!Number.isSafeInteger(version) || version < 1) {
    throw new Error(`Cannot render an invalid protocol version: ${version}`);
  }
  if (!Array.isArray(methods) || methods.length === 0) {
    throw new Error("Cannot render a protocol module without methods");
  }
  if (methods.some((method) => typeof method !== "string" || method.length === 0)) {
    throw new Error("Cannot render invalid protocol method names");
  }
  const renderedMethods = methods.map((method) => `  ${JSON.stringify(method)},`).join("\n");
  return (
    `${GENERATED_HEADER}\n` +
    `export const APP_SERVER_PROTOCOL_VERSION = ${version} as const;\n\n` +
    "export const APP_SERVER_PROTOCOL_METHODS = [\n" +
    `${renderedMethods}\n] as const;\n\n` +
    "export type AppServerProtocolMethod = (typeof APP_SERVER_PROTOCOL_METHODS)[number];\n"
  );
}

/** Throw when a generated module is missing or differs from the Rust source. */
export function checkGeneratedProtocolModule(
  generatedSource,
  version,
  methods,
  generatedName = "TypeScript protocol module",
) {
  const expected = renderProtocolModule(version, methods);
  const normalize = (value) => value.replace(/\r\n/g, "\n");
  if (normalize(generatedSource) !== expected) {
    throw new Error(
      `${generatedName} is out of date; run ` +
        "`npm.cmd --prefix rust\\gui run protocol:generate`",
    );
  }
}

function usage() {
  return [
    "Usage: node scripts/check-protocol-version.mjs --check|--write",
    "  --check  Verify the checked-in TypeScript protocol module matches Rust.",
    "  --write  Regenerate the TypeScript protocol module from Rust.",
  ].join("\n");
}

async function run(args) {
  if (args.length !== 1 || !["--check", "--write"].includes(args[0])) {
    throw new Error(usage());
  }
  const rustSource = await readFile(RUST_PROTOCOL_SOURCE, "utf8");
  const rustSourceName = path.relative(REPOSITORY_ROOT, RUST_PROTOCOL_SOURCE);
  const version = extractProtocolVersion(rustSource, rustSourceName);
  const methods = extractProtocolMethods(
    rustSource,
    rustSourceName,
  );
  let current = "";
  try {
    current = await readFile(TYPESCRIPT_PROTOCOL_TARGET, "utf8");
  } catch (error) {
    if (error?.code !== "ENOENT") throw error;
  }
  const expected = renderProtocolModule(version, methods);
  if (args[0] === "--write") {
    // Keep the checkout's existing line-ending convention when regenerating.
    const eol = current.includes("\r\n") ? "\r\n" : "\n";
    await writeFile(TYPESCRIPT_PROTOCOL_TARGET, expected.replaceAll("\n", eol));
    console.log(
      `Generated ${path.relative(REPOSITORY_ROOT, TYPESCRIPT_PROTOCOL_TARGET)} ` +
        `for protocol version ${version}.`,
    );
    return;
  }
  checkGeneratedProtocolModule(
    current,
    version,
    methods,
    path.relative(REPOSITORY_ROOT, TYPESCRIPT_PROTOCOL_TARGET),
  );
  console.log(`Protocol contract v${version} is in sync (${methods.length} methods).`);
}

const invokedPath = process.argv[1] && path.resolve(process.argv[1]);
if (invokedPath && pathToFileURL(invokedPath).href === import.meta.url) {
  try {
    await run(process.argv.slice(2));
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}
